import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"兑下震上 归妹：","description":"京氏易传 - 兑下震上 归妹：","frontmatter":{"title":"兑下震上 归妹：","description":"京氏易传 - 兑下震上 归妹："},"headers":[],"relativePath":"zh/classics/jingshi/065.md","filePath":"zh/classics/jingshi/065.md"}'),r={name:"zh/classics/jingshi/065.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"兑下震上-归妹",tabindex:"-1"},[i("兑下震上 归妹： "),e("a",{class:"header-anchor",href:"#兑下震上-归妹","aria-label":"Permalink to “兑下震上 归妹：”"},"​")],-1),e("p",null,"阴复于本，悦动于外，二气不交，故曰归妹。【归者，嫁也。】互见离坎，同于未济，适阳从阴，刚从外至。九四至刚，六三悦柔，返无其应，凶。兑羊涉卦之终，长何吉也。与艮为飞伏。【丁丑土，丙申金。】三公归魂之世，上六宗庙见应。",-1),e("p",null,"建始甲子至己巳，【大雪，小满。】积算起己巳至戊辰，周而复始。水土入震兑。【分水土二象入兑宫。】",-1),e("p",null,"五星从位起岁星，【木星东方入兑宫归魂。】轸宿从位降丁丑土，【二十八宿，分轸宿入兑归魂六二（三之误）丁丑土上，分吉凶起算。】分气候三十八。【积算起三十八数，六位推五行数吉凶。】（虎易注：此处的三十八，疑为有误。）",-1),e("p",null,"雷居泽上，刚气亢盛，阴阳不何，进退危也。【震长男，兑少女，少女匹长男，气非合也。】吉凶在上六，处于动极，适变位定，时不可移之道也。五行考象，非合斯义，阴阳运动，适当何爻。或阴或阳，或柔或刚，升降六位，非取一也。【兑归魂，配六十四卦之终也。】",-1)])])}const f=s(r,[["render",l]]);export{_ as __pageData,f as default};
